#!/bin/bash
# Delivery: REAL selective regeneration (Stages 11 + 12).
#
# Writes the files below into the target repo, backing up only those that
# actually differ, then verifies every one by sha256. Safe to re-run: a
# second run reports everything unchanged and creates no backups.
#
# Usage:  bash install_regen.sh [target-dir]        (default: $HOME/NLP_Lab)

set -euo pipefail
TARGET="${1:-$HOME/NLP_Lab}"
STAMP="$(date +%Y%m%d-%H%M%S)"
if [ ! -d "$TARGET" ]; then echo "FATAL: no such directory: $TARGET"; exit 1; fi
if [ ! -d "$TARGET/scripts" ] || [ ! -d "$TARGET/src/probe_extraction" ]; then
  echo "FATAL: $TARGET does not look like the NLP_Lab repo."; exit 1; fi
cd "$TARGET"
echo "Installing into: $TARGET"
echo ""
N_NEW=0; N_UPD=0; N_SAME=0; N_DEL=0

write_file() {  # $1 path, $2 sha256, $3 mode
  local path="$1" want="$2" mode="$3" tmp
  mkdir -p "$(dirname "$path")"
  tmp="$(mktemp)"
  base64 --decode > "$tmp"
  local got; got="$(sha256sum "$tmp" | cut -d" " -f1)"
  if [ "$got" != "$want" ]; then
    echo "  FATAL: $path decoded to $got, expected $want"; rm -f "$tmp"; exit 1; fi
  if [ -f "$path" ]; then
    local cur; cur="$(sha256sum "$path" | cut -d" " -f1)"
    if [ "$cur" = "$want" ]; then
      echo "  unchanged  $path"; rm -f "$tmp"; N_SAME=$((N_SAME+1)); return 0; fi
    cp -p "$path" "${path}.bak.${STAMP}"
    echo "  updated    $path   (backup: ${path}.bak.${STAMP})"; N_UPD=$((N_UPD+1))
  else
    echo "  new        $path"; N_NEW=$((N_NEW+1))
  fi
  cat "$tmp" > "$path"; rm -f "$tmp"; chmod "$mode" "$path"
}

echo "--- files ---"
